import { Router } from 'express';
import { BillingSuiteController } from './billing-suite.controller';

const router = Router();

router.get('/billing-suite', BillingSuiteController.list);
router.post('/billing-suite', BillingSuiteController.create);

export { router as billing-suiteRouter };

import { Request, Response } from 'express';
import { BillingSuiteService } from './billing-suite.service';

export const BillingSuiteController = {
  async list(_req: Request, res: Response) {
    const data = await BillingSuiteService.list();
    return res.json(data);
  },

  async create(req: Request, res: Response) {
    const created = await BillingSuiteService.create(req.body);
    return res.status(201).json(created);
  },
};

import { BillingSuiteRepository } from './billing-suite.repository';

export const BillingSuiteService = {
  list() {
    return BillingSuiteRepository.list();
  },

  create(payload: { name: string; description?: string }) {
    return BillingSuiteRepository.create(payload);
  },
};

const memoryStore: Array<{ id: string; name: string; description?: string }> = [];

export const BillingSuiteRepository = {
  list() {
    return memoryStore;
  },

  create(payload: { name: string; description?: string }) {
    const item = { id: String(Date.now()), ...payload };
    memoryStore.unshift(item);
    return item;
  },
};

import { request } from '../services/http/request';

export function listBillingSuite() {
  return request<Array<{ id: string; name: string }>>({ method: 'GET', url: '/billing-suite' });
}

export function createBillingSuite(payload: { name: string; description?: string }) {
  return request<{ id: string; name: string }>({ method: 'POST', url: '/billing-suite', data: payload });
}

import { useEffect, useState } from 'react';
import { listBillingSuite } from '../../services/billing-suiteApi';

export function BillingSuiteModule() {
  const [items, setItems] = useState<Array<{ id: string; name: string }>>([]);

  useEffect(() => {
    void listBillingSuite().then(setItems);
  }, []);

  return (
    <section className="rounded-xl border border-slate-200 bg-white p-4">
      <h3 className="text-base font-semibold">Billing Suite Module</h3>
      <ul className="mt-3 space-y-2 text-sm text-slate-600">
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>
    </section>
  );
}

